"""Fill parsing, pairing, and aggressive-order extraction."""

from __future__ import annotations

from typing import List

import numpy as np
import pandas as pd


def pair_fills(fills_df: pd.DataFrame) -> pd.DataFrame:
    """Pair the taker and maker sides of each trade.

    The taker and maker halves are identified via:

    * ``is_taker`` boolean column (preferred, generated by
      :func:`~data_generator.generate_fills`), or
    * ``role`` column with values ``'taker'`` / ``'maker'`` (legacy format).

    The two halves are joined on ``(day, market, trade_id)`` – using the
    calendar day as an extra key prevents spurious cross-day matches when
    trade IDs are recycled.  ``day`` is derived from ``fill_time``, which may
    be either a Unix float (seconds) or a ``pd.Timestamp``/``datetime64``.

    Parameters
    ----------
    fills_df:
        Raw fills DataFrame with columns: ``fill_time``, ``market``,
        ``trade_id``, ``wallet``, ``side``, ``notional``, ``is_twap``,
        ``is_liquidation``, and either ``is_taker`` or ``role``.

    Returns
    -------
    DataFrame with one row per taker fill, containing all taker columns plus
    ``maker_wallet`` from the matched maker fill.
    """
    df = fills_df.copy()

    # ── Compute integer day key ──────────────────────────────────────────
    ft = df["fill_time"]
    if pd.api.types.is_datetime64_any_dtype(ft) or isinstance(
        ft.iloc[0] if len(ft) else None, pd.Timestamp
    ):
        df["day"] = ft.dt.normalize().astype(np.int64)
    else:
        df["day"] = (ft.astype(float) // 86_400).astype(np.int64)

    # ── Split into taker and maker subsets ──────────────────────────────
    if "is_taker" in df.columns:
        taker_mask = df["is_taker"].astype(bool)
    elif "role" in df.columns:
        taker_mask = df["role"] == "taker"
    else:
        raise ValueError("fills_df must contain either 'is_taker' or 'role' column")

    takers = df[taker_mask].copy()
    makers = df[~taker_mask][["day", "market", "trade_id", "wallet"]].copy()
    makers = makers.rename(columns={"wallet": "maker_wallet"})

    paired = takers.merge(makers, on=["day", "market", "trade_id"], how="left")

    # Drop helper columns added here; preserve original schema
    drop_cols = [c for c in ["is_taker", "role"] if c in paired.columns]
    return paired.drop(columns=drop_cols)


def group_aggressive_orders(paired_fills: pd.DataFrame) -> pd.DataFrame:
    """Aggregate paired taker fills into order-level aggressive-order events.

    Multiple partial fills sharing an ``order_id`` are collapsed into a single
    order record.  Direction is encoded as ``+1`` (buy) or ``-1`` (sell).

    Parameters
    ----------
    paired_fills:
        Output of :func:`pair_fills` (rows represent taker legs with
        ``order_id``, ``wallet``, ``market``, ``side``, ``notional``,
        ``fill_time``, ``is_twap``, ``is_liquidation``).

    Returns
    -------
    DataFrame with columns: ``order_id``, ``wallet``, ``market``,
    ``direction``, ``notional``, ``event_time``, ``is_twap``,
    ``is_liquidation``.
    """
    if paired_fills.empty:
        return pd.DataFrame(
            columns=[
                "order_id",
                "wallet",
                "market",
                "direction",
                "notional",
                "event_time",
                "is_twap",
                "is_liquidation",
            ]
        )

    def _agg(grp: pd.DataFrame) -> pd.Series:
        return pd.Series(
            {
                "wallet": grp["wallet"].iloc[0],
                "market": grp["market"].iloc[0],
                "direction": 1 if grp["side"].iloc[0] == "buy" else -1,
                "notional": grp["notional"].sum(),
                "event_time": grp["fill_time"].min(),
                "is_twap": bool(grp["is_twap"].any()),
                "is_liquidation": bool(grp["is_liquidation"].any()),
            }
        )

    orders = (
        paired_fills.groupby("order_id", sort=False)
        .apply(_agg, include_groups=False)
        .reset_index()
    )
    return orders[
        [
            "order_id",
            "wallet",
            "market",
            "direction",
            "notional",
            "event_time",
            "is_twap",
            "is_liquidation",
        ]
    ]


def filter_qualifying_orders(orders: pd.DataFrame) -> pd.DataFrame:
    """Exclude TWAP and liquidation orders, keeping only qualifying aggressives.

    Parameters
    ----------
    orders:
        Orders DataFrame with boolean columns ``is_twap`` and
        ``is_liquidation``.

    Returns
    -------
    Filtered copy of *orders* with TWAP and liquidation rows removed.
    """
    mask = (~orders["is_twap"]) & (~orders["is_liquidation"])
    return orders[mask].copy()
